from common import *

def solve(record):
 fid,m,i=role(record);slug=fid.split('-',3)[3];A,p=expected(record)
 if slug=='odd-even':
  h=s.pi/m
  return result(record,[T('The cubic term is odd, so its integral over the symmetric interval is zero. The cosine term is even.'),r'\int_{-'+tex(h)+'}^{'+tex(h)+r'}x^3\,\mathrm dx=0,\qquad \int_{-'+tex(h)+'}^{'+tex(h)+r'}\cos x\,\mathrm dx=2\int_0^{'+tex(h)+r'}\cos x\,\mathrm dx',r'2[\sin x]_0^{'+tex(h)+r'}=2\sin\left('+tex(h)+r'\right)='+tex(A)],[ck('The odd cubic contributes zero on the concrete symmetric bounds',s.integrate(x**3,(x,-h,h)),0),ck('The actual even cosine primitive differentiates correctly',s.diff(s.sin(x),x),s.cos(x)),ck('Symmetry leaves the correctly evaluated cosine integral',2*s.sin(h),A)],['unused-builder-parameter','unbound-antiderivative-endpoints'])
 if p.get('_input',{}).get('kind')=='integral':
  _,expr,F,lo,hi=integral_input(record);pre=[];idea=None
  if slug=='signed-area':pre=[T('The line crosses the horizontal axis halfway through the interval; the two triangular signed areas cancel.'),r'-\frac12('+tex(m)+r')('+tex(m)+r')+\frac12('+tex(m)+r')('+tex(m)+r')=0']
  elif slug=='substitution-affine':pre=[r'u='+tex(m)+r'x+1,\qquad \mathrm du='+tex(m)+r'\,\mathrm dx',r'\int_0^1('+tex(m)+r'x+1)^2\,\mathrm dx=\frac1{'+tex(m)+r'}\int_1^{'+tex(m+1)+r'}u^2\,\mathrm du']
  elif slug=='log-recognition':idea='The denominator is positive throughout the interval, so its natural logarithm is an antiderivative.'
  elif slug=='exponential-rate':pre=[r'\frac{\mathrm d}{\mathrm dx}e^{'+tex(m)+r'x}='+tex(m)+r'e^{'+tex(m)+r'x}',T('Divide by the constant inner derivative before evaluating the endpoints.')]
  elif slug=='area-between-curves':pre=[r'x^2='+tex(m)+r'x\ \Longleftrightarrow\ x=0\ \textnormal{or}\ x='+tex(m),r''+tex(m)+r'x-x^2=x('+tex(m)+r'-x)\ge0\quad(0\le x\le '+tex(m)+r')',T('The enclosed area is the integral of the upper curve minus the lower curve.')]
  elif slug=='parts-log':pre=[r'u=\ln x,\quad \mathrm dv=\mathrm dx,\quad \mathrm du=\frac{\mathrm dx}{x},\quad v=x',r'\int\ln x\,\mathrm dx=x\ln x-\int1\,\mathrm dx=x\ln x-x+C,\qquad C\in\mathbb R']
  elif slug=='partial-fractions':pre=[r'\frac1{(x+1)(x+'+tex(m)+r')}=\frac1{'+tex(m-1)+r'}\left(\frac1{x+1}-\frac1{x+'+tex(m)+r'}\right)']
  elif slug=='rational-power-substitution':pre=[r'u=1+x^2,\quad\mathrm du=2x\,\mathrm dx,\qquad\int_0^1\frac{2x}{(1+x^2)^{'+tex(m)+r'}}\,\mathrm dx=\int_1^2u^{-'+tex(m)+r'}\,\mathrm du']
  elif slug=='trig-odd-power':pre=[r'u=\cos x,\quad\mathrm du=-\sin x\,\mathrm dx',r'\int_0^{\pi/2}\sin x\cos^{'+tex(m)+r'}x\,\mathrm dx=-\int_1^0u^{'+tex(m)+r'}\,\mathrm du']
  elif slug=='secant-square-substitution':pre=[r'u=\tan x,\quad\mathrm du=\sec^2x\,\mathrm dx',r'\int_0^{\pi/4}\tan^{'+tex(m)+r'}x\sec^2x\,\mathrm dx=\int_0^1u^{'+tex(m)+r'}\,\mathrm du']
  elif slug=='inverse-tangent':pre=[r'u=\frac{x}{'+tex(m)+r'},\quad\mathrm dx='+tex(m)+r'\,\mathrm du',r'\int_0^{'+tex(m)+r'}\frac{\mathrm dx}{x^2+'+tex(m*m)+r'}=\frac1{'+tex(m)+r'}\int_0^1\frac{\mathrm du}{1+u^2}']
  elif slug=='nested-log':pre=[r'u=\ln x,\quad\mathrm du=\frac{\mathrm dx}{x},\qquad\int_e^{e^{'+tex(m)+r'}}\frac{\mathrm dx}{x\ln x}=\int_1^{'+tex(m)+r'}\frac{\mathrm du}{u}']
  elif slug=='improper-exponential':idea='The exponent is negative with a positive decay rate. Evaluate the improper upper endpoint by a limit.'
  elif slug=='moving-boundary-area':pre=[r'\sqrt{x}=\frac{x}{'+tex(m)+r'}\ \Longleftrightarrow\ x=0\ \textnormal{or}\ x='+tex(m*m),r'\sqrt{x}-\frac{x}{'+tex(m)+r'}\ge0\quad(0\le x\le '+tex(m*m)+r')',T('Integrate the vertical difference between the curves on their intersection interval.')]
  elif slug=='exponential-trig':pre=[r'I(x)=\int_0^xe^t\cos('+tex(m)+r't)\,\mathrm dt,\quad J(x)=\int_0^xe^t\sin('+tex(m)+r't)\,\mathrm dt',T('Integration by parts gives a pair of equations for these definite primitives.'),r'I(x)=e^x\cos('+tex(m)+r'x)-1+'+tex(m)+r'J(x),\quad J(x)=e^x\sin('+tex(m)+r'x)-'+tex(m)+r'I(x)',r'('+tex(1+m*m)+r')I(x)=e^x\big(\cos('+tex(m)+r'x)+'+tex(m)+r'\sin('+tex(m)+r'x)\big)-1']
  elif slug=='improper-rational-beta':pre=[r'u=\frac{x}{1+x},\quad x=\frac{u}{1-u},\quad\mathrm dx=\frac{\mathrm du}{(1-u)^2}',r'\frac{x^{'+tex(m)+r'}}{(1+x)^{'+tex(m+2)+r'}}\,\mathrm dx=u^{'+tex(m)+r'}\,\mathrm du,\qquad x:0\to\infty\ \Longrightarrow\ u:0\to1']
  elif slug=='trig-log':pre=[r'u=\sin x,\quad\mathrm du=\cos x\,\mathrm dx',r'\int_0^{\pi/2}\cos x\sin^{'+tex(m)+r'}x\ln(\sin x)\,\mathrm dx=\int_0^1u^{'+tex(m)+r'}\ln u\,\mathrm du',T('Integrate by parts after this substitution; the logarithmic endpoint must be taken as a limit.')]
  elif slug=='root-quadratic':pre=[r'x='+tex(m)+r'\sinh u,\quad\sqrt{x^2+'+tex(m*m)+r'}='+tex(m)+r'\cosh u,\quad\mathrm dx='+tex(m)+r'\cosh u\,\mathrm du',r'\sinh^2u=\frac{\cosh(2u)-1}{2},\qquad\operatorname{arsinh}v=\ln(v+\sqrt{1+v^2})']
  elif slug=='reciprocal-quartic':pre=[r'\frac1{(x^2+1)(x^2+'+tex(m*m)+r')}=\frac1{'+tex(m*m-1)+r'}\left(\frac1{x^2+1}-\frac1{x^2+'+tex(m*m)+r'}\right)',r'\lim_{b\to\infty}\arctan b=\lim_{b\to\infty}\arctan\frac{b}{'+tex(m)+r'}=\frac\pi2']
  out=antiderivative_steps(record,idea,pre)
  out['checks']+=transform_checks(slug,m)
  return out
 if slug=='absolute-area':
  val=s.integrate(m-x,(x,0,m))+s.integrate(x-m,(x,m,2*m))
  return result(record,[r'|x-'+tex(m)+r'|=\begin{cases}'+tex(m)+r'-x,&0\le x\le '+tex(m)+r',\\x-'+tex(m)+r',&'+tex(m)+r'\le x\le '+tex(2*m)+r'.\end{cases}',r'\int_0^{'+tex(2*m)+r'}|x-'+tex(m)+r'|\,\mathrm dx=\int_0^{'+tex(m)+r'}('+tex(m)+r'-x)\,\mathrm dx+\int_{'+tex(m)+'}^{'+tex(2*m)+r'}(x-'+tex(m)+r')\,\mathrm dx',tex(m*m/2)+'+'+tex(m*m/2)+'='+tex(A)],[ck('Two sign-correct interval integrals',val,A)],['missing-concrete-split'])
 if slug=='quarter-disk':return result(record,[r'y=\sqrt{'+tex(m*m)+r'-x^2}\ \Longrightarrow\ x^2+y^2='+tex(m*m)+r',\quad x,y\ge0',T('The region is a quarter disk with the displayed radius.'),r'\textnormal{Area}=\frac14\pi('+tex(m)+r')^2='+tex(A)],[ck('Quarter disk integral by a branch-safe trigonometric substitution',s.integrate(m*m*s.cos(t)**2,(t,0,s.pi/2)),A)],['unused-builder-parameter'])
 if slug=='average-value':return result(record,[T('The average value is the integral divided by the interval length.'),r'\frac1{'+tex(m)+r'-0}\int_0^{'+tex(m)+r'}x^2\,\mathrm dx=\frac1{'+tex(m)+r'}\left[\frac{x^3}{3}\right]_0^{'+tex(m)+'}='+tex(A)],[ck('Integral average with the actual interval length',s.integrate(x*x,(x,0,m))/m,A)],['unused-builder-parameter'])
 if slug=='accumulation-from-derivative':return result(record,[T('The stated continuous differentiability allows the Fundamental Theorem of Calculus.'),r'\int_1^3 F\prime(x)\,\mathrm dx=F(3)-F(1)='+tex(m*m+1)+'-'+tex(m)+'='+tex(A)],[ck('The supplied endpoint values are subtracted in the correct order',m*m+1-m,A)],['unbound-generic-endpoints'])
 if slug=='piecewise-accumulation':return result(record,[T('Split the integral where the formula changes.'),r'\int_0^2 f(x)\,\mathrm dx=\int_0^1 '+tex(m)+r'x\,\mathrm dx+\int_1^2 '+tex(m+1)+r'\,\mathrm dx',r'\left[\frac{'+tex(m)+r'x^2}{2}\right]_0^1+\left['+tex(m+1)+r'x\right]_1^2='+tex(m/2)+'+'+tex(m+1)+'='+tex(A)],[ck('The correct formula is integrated on each interval',s.integrate(m*x,(x,0,1))+s.integrate(m+1,(x,1,2)),A)],['missing-concrete-interval-calculation'])
 if slug=='washer-volume':return result(record,[T('Each cross-section perpendicular to the axis is a disk. Its radius is the height of the line.'),r'V=\pi\int_0^1('+tex(m)+r'x)^2\,\mathrm dx='+tex(s.pi*m*m)+r'\left[\frac{x^3}{3}\right]_0^1='+tex(A)],[ck('Disk area, not radius, is integrated',s.pi*s.integrate(m*m*x*x,(x,0,1)),A)],['unused-builder-parameter'])
 if slug=='shell-volume':return result(record,[T('Use cylindrical shells: circumference times height times thickness.'),r'V=2\pi\int_0^{'+tex(m)+r'}x('+tex(m)+r'-x)\,\mathrm dx',r'V=2\pi\left[\frac{'+tex(m)+r'x^2}{2}-\frac{x^3}{3}\right]_0^{'+tex(m)+'}='+tex(A)],[ck('Shell radius and height are both retained',2*s.pi*s.integrate(x*(m-x),(x,0,m)),A)],['unused-builder-parameter'])
 if slug=='piecewise-absolute-root':
  cut=m*m/4;v1=s.integrate(m/2-s.sqrt(x),(x,0,cut));v2=s.integrate(s.sqrt(x)-m/2,(x,cut,m*m))
  return result(record,[r'\sqrt{x}='+tex(m/2)+r'\ \Longleftrightarrow\ x='+tex(cut),r'\int_0^{'+tex(m*m)+r'}\left|\sqrt{x}-'+tex(m/2)+r'\right|\,\mathrm dx=\int_0^{'+tex(cut)+r'}\left('+tex(m/2)+r'-\sqrt{x}\right)\,\mathrm dx+\int_{'+tex(cut)+'}^{'+tex(m*m)+r'}\left(\sqrt{x}-'+tex(m/2)+r'\right)\,\mathrm dx',tex(v1)+'+'+tex(v2)+'='+tex(A)],[ck('The absolute-value split has the correct nonlinear crossing',v1+v2,A)],['missing-concrete-split'])
 if slug=='logarithmic-moment':
  a=s.symbols('alpha',real=True)
  return result(record,[r'J(\alpha)=\int_0^1x^\alpha\,\mathrm dx=\frac1{\alpha+1},\qquad\alpha>-1',T('Differentiate twice with respect to the exponent. Nearby exponents give an integrable power-logarithm bound, which justifies both differentiations.'),r'J^{\prime\prime}(\alpha)=\int_0^1x^\alpha(\ln x)^2\,\mathrm dx=\frac2{(\alpha+1)^3}',r'J^{\prime\prime}('+tex(m)+r')=\frac2{('+tex(m)+r'+1)^3}='+tex(A)],[ck('The second exponent derivative of the integrand supplies the stated logarithmic square',s.diff(s.Symbol('X',positive=True)**a,a,2),s.Symbol('X',positive=True)**a*s.log(s.Symbol('X',positive=True))**2),ck('Second exponent derivative at the displayed exponent',s.diff(1/(a+1),a,2).subs(a,m),A)],['undeclared-parameter-role','omitted-convergence-condition'])
 if slug=='beta-polynomial':return result(record,[T('For nonnegative integer endpoint powers, repeated integration by parts gives the beta factorial identity.'),r'\int_0^1x^p(1-x)^q\,\mathrm dx=\frac{p!q!}{(p+q+1)!},\qquad p,q\in\mathbb Z_{\ge0}',r'\int_0^1x^{'+tex(m)+r'}(1-x)^{'+tex(m+1)+r'}\,\mathrm dx=\frac{'+tex(m)+r'!\,'+tex(m+1)+r'!}{'+tex(2*m+2)+r'!}='+tex(A)],[ck('An independent polynomial integral matches the factorial evaluation',s.integrate(s.expand(x**m*(1-x)**(m+1)),(x,0,1)),A)],['missing-identity-specialization'])
 if slug=='arc-length-perfect-square':
  slope=x/(2*m)-m/(2*x);speed=x/(2*m)+m/(2*x)
  return result(record,[r'y\prime(x)='+tex(slope),r'1+(y\prime(x))^2=\left('+tex(speed)+r'\right)^2',T('The expression in parentheses is positive on the given interval, so it is the speed.'),r'L=\int_1^2\sqrt{1+(y\prime(x))^2}\,\mathrm dx=\int_1^2\left('+tex(speed)+r'\right)\,\mathrm dx',r'L=\left['+tex(x*x/(4*m)+m*s.log(x)/2)+r'\right]_1^2='+tex(A)],[ck('The actual graph derivative gives the squared speed',1+slope*slope,speed*speed),ck('The positive speed integrates to the original length',s.integrate(speed,(x,1,2)),A)],['missing-endpoint-evaluation'])
 if slug=='Frullani-rectangle':return result(record,[r'\frac{e^{-x}-e^{-'+tex(m)+r'x}}x=\int_1^{'+tex(m)+r'}e^{-tx}\,\mathrm dt\qquad(x>0)',T('The double integrand is nonnegative, so Tonelli permits reversing the order before assuming convergence.'),r'\int_0^\infty\int_1^{'+tex(m)+r'}e^{-tx}\,\mathrm dt\,\mathrm dx=\int_1^{'+tex(m)+r'}\left(\int_0^\infty e^{-tx}\,\mathrm dx\right)\,\mathrm dt=\int_1^{'+tex(m)+r'}\frac{\mathrm dt}{t}',r'[\ln t]_1^{'+tex(m)+'}='+tex(A)],[ck('The auxiliary parameter integral equals the original combined integrand',s.integrate(s.exp(-t*s.Symbol('X',positive=True)),(t,1,m)),(s.exp(-s.Symbol('X',positive=True))-s.exp(-m*s.Symbol('X',positive=True)))/s.Symbol('X',positive=True)),ck('The parameter integral is finite and gives the original answer',s.integrate(1/t,(t,1,m)),A)],['named-identity-without-application','improper-cancellation-not-explained'])
 if slug=='mixed-log-endpoints':
  q=m+k;moment=-x**(q+1)*s.log(x)/(q+1)+x**(q+1)/(q+1)**2
  r=m+1;decomp=1/(r*r*k)-1/(r*r*(k+r))-1/(r*(k+r)**2);v=s.harmonic(r)/r**2-(s.pi**2/6-s.harmonic(r,2))/r
  return result(record,[r'-\ln(1-x)=\sum_{k=1}^\infty\frac{x^k}{k}\qquad(0\le x<1)',T('Multiply by the nonnegative power-logarithm factor and use Tonelli. Each resulting logarithmic moment follows by integration by parts.'),r'\int_0^1-x^q\ln x\,\mathrm dx=\left[-\frac{x^{q+1}\ln x}{q+1}+\frac{x^{q+1}}{(q+1)^2}\right]_0^1=\frac1{(q+1)^2}\quad(q>-1)',T('The lower endpoint is a limit: a positive power times the logarithm tends to zero.'),r'\int_0^1x^{'+tex(m)+r'}\ln x\ln(1-x)\,\mathrm dx=\sum_{k=1}^\infty\frac1{k(k+'+tex(r)+r')^2}',r'\frac1{k(k+'+tex(r)+r')^2}=\frac1{'+tex(r*r)+r'}\left(\frac1k-\frac1{k+'+tex(r)+r'}\right)-\frac1{'+tex(r)+r'(k+'+tex(r)+r')^2}',r'\frac1{'+tex(r*r)+r'}\sum_{j=1}^{'+tex(r)+r'}\frac1j-\frac1{'+tex(r)+r'}\left(\frac{\pi^2}{6}-\sum_{j=1}^{'+tex(r)+r'}\frac1{j^2}\right)='+tex(A)],[ck('The termwise logarithmic-moment primitive differentiates exactly',s.diff(moment,x),-x**q*s.log(x)),ck('The upper endpoint of the primitive gives the displayed reciprocal square',moment.subs(x,1),1/(k+m+1)**2),ck('The partial-fraction decomposition is exact',decomp,1/(k*(k+r)**2)),ck('The two finite harmonic tails give the original answer',v,A)],['opaque-special-function-step','missing-series-justification'],['Uses a transparent positive-series derivation instead of an unexplained mixed beta derivative; the original parameter-differentiation technique remains a valid alternative.'])
 if slug=='half-angle-quadratic':
  d=s.sqrt(m*m-1);G=s.log((t+m-d)/(t+m+d))/d
  return result(record,[r't=\tan\frac x2,\quad\sin x=\frac{2t}{1+t^2},\quad\mathrm dx=\frac{2\,\mathrm dt}{1+t^2},\quad x:0\to\frac\pi2\ \Longrightarrow\ t:0\to1',r'\int_0^{\pi/2}\frac{\mathrm dx}{1+'+tex(m)+r'\sin x}=\int_0^1\frac{2\,\mathrm dt}{t^2+'+tex(2*m)+r't+1}',r'G(t)='+tex(G)+r',\qquad G\prime(t)=\frac2{t^2+'+tex(2*m)+r't+1}',T('Both linear factors inside the logarithm are positive throughout the transformed interval.'),r'G(1)-G(0)='+tex(A)],[ck('The half-angle substitution and Jacobian give the stated rational kernel',2/(1+t*t)/(1+m*2*t/(1+t*t)),2/(t*t+2*m*t+1)),ck('The logarithmic derivative is the transformed rational integrand',s.diff(G,t),2/(t*t+2*m*t+1)),ck('The concrete transformed endpoints give the original answer',G.subs(t,1)-G.subs(t,0),A)],['unbound-endpoints','missing-branch-condition'])
 raise KeyError(fid)


def transform_checks(slug,m):
 U=s.Symbol('U',positive=True);out=[]
 if slug=='substitution-affine':out=[ck('Affine substitution carries the inverse Jacobian',((m*((U-1)/m)+1)**2)/m,U*U/m),ck('Affine substitution gives the displayed upper endpoint',(m*x+1).subs(x,1),m+1)]
 if slug=='partial-fractions':out=[ck('The displayed simple-pole partial fractions are exact',1/((x+1)*(x+m)),(1/(x+1)-1/(x+m))/(m-1))]
 if slug=='rational-power-substitution':out=[ck('The numerator is exactly the derivative of the substituted denominator',s.diff(1+x*x,x),2*x)]
 if slug=='trig-odd-power':out=[ck('The cosine substitution has the required negative derivative',s.diff(s.cos(x),x),-s.sin(x)),ck('The cosine substitution reverses the upper endpoint',s.cos(s.pi/2),0)]
 if slug=='secant-square-substitution':out=[ck('The tangent substitution absorbs the secant-square factor',s.diff(s.tan(x),x),1/s.cos(x)**2),ck('The tangent upper endpoint is one',s.tan(s.pi/4),1)]
 if slug=='inverse-tangent':out=[ck('Scaling the inverse-tangent kernel preserves the inverse scale',m/((m*U)**2+m*m),1/(m*(1+U*U)))]
 if slug=='nested-log':out=[ck('The exponential inverse substitution transforms the logarithmic kernel',s.exp(U)/(s.exp(U)*s.log(s.exp(U))),1/U)]
 if slug=='improper-rational-beta':out=[ck('The rational inverse substitution and Jacobian cancel all remaining denominator factors',(U/(1-U))**m/(1+U/(1-U))**(m+2)/(1-U)**2,U**m)]
 if slug=='root-quadratic':out=[ck('The hyperbolic substitution has the claimed positive square-root branch',s.sqrt((m*s.sinh(x))**2+m*m),m*s.cosh(x)),ck('The double-angle reduction is exact',s.expand_trig(s.cosh(2*x)),1+2*s.sinh(x)**2)]
 if slug=='reciprocal-quartic':out=[ck('The squared-pole partial-fraction decomposition is exact',1/((x*x+1)*(x*x+m*m)),(1/(x*x+1)-1/(x*x+m*m))/(m*m-1))]
 if slug=='exponential-trig':
  I=(s.exp(x)*(s.cos(m*x)+m*s.sin(m*x))-1)/(1+m*m)
  J=(s.exp(x)*(s.sin(m*x)-m*s.cos(m*x))+m)/(1+m*m)
  out=[ck('The first parts equation is satisfied by both definite primitives',I,s.exp(x)*s.cos(m*x)-1+m*J),ck('The second parts equation is satisfied without an unknown integration constant',J,s.exp(x)*s.sin(m*x)-m*I),ck('The first definite primitive is zero at its lower endpoint',I.subs(x,0),0),ck('The second definite primitive is zero at its lower endpoint',J.subs(x,0),0)]
 return out
